int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev)
{
    int ret = 0;

    /* Sanity checks on the geometry parameters */
    if (!g || g->sector <= 0 || g->head <= 0 || g->track <= 0) {
        return -EINVAL;
    }

    if (type == FLOPPY_TYPE_USER) {
        /* Check for administrative permissions */
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }

        /* Lock the floppy disk controller */
        if (floppy_controller_lock(drive)) {
            return -EINTR;
        }

        /* Update the floppy type and sizes */
        current_floppy[drive] = type;
        floppy_sizes[drive] = g;

    } else {
        /* Handle non-user-defined geometry settings */
        if (cmd == FDC_EXECUTE) {
            if (invalidate_drive(drive)) {
                ret = -EINVAL;
            } else {
                current_drive_params[drive] = *g;
            }
        } else {
            ret = -EINVAL;
        }
    }

    return ret;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    int ret = 0;

    if (!g || drive < 0 || drive >= N_DRIVE) {
        return -EINVAL;
    }

    if (type == FLOPPY_TYPE_USER) {
        if (!capable(CAP_SYS_ADMIN))
            return -EPERM;

        if (lock_fdc(0)) {
            return -EINTR;
        }

        if (g->track > 255 || g->head > 1 || g->sector > 128 || g->stretch > 1) {
            unlock_fdc();
            return -EINVAL;
        }

        FDC_STATE->track[drive] = -1;
        floppy_type[drive] = g;
        update_drive_params(drive);
        unlock_fdc();
    } else {
        if (cmd == FDDEFPRM) {
            if (lock_fdc(0)) {
                return -EINTR;
            }

            current_drive_params[drive] = *g;
            unlock_fdc();
        } else {
            invalidate_drive(drive);
        }
    }

    return ret;
}

