int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    int ret = 0;

    if (!g || drive < 0 || drive >= N_DRIVE || !bdev)
        return -EINVAL;

    if (type == FLOPPY_USER_DEFINED) {
        if (!capable(CAP_SYS_ADMIN))
            return -EPERM;

        if (lock_fdc(0))
            return -EINTR;

        current_floppy = &FDC_STATE(drive).floppy;
        current_floppy->size = 0;
        current_floppy->type = type;
        current_floppy->stretch = g->stretch;
        current_floppy->tracks = g->track;
        current_floppy->heads = g->head;
        current_floppy->sectors = g->sector;
        unlock_fdc(0);
    } else {
        if (cmd == FDPRESET) {
            invalidate_drive(drive);
            return 0;
        }
        ret = -EINVAL;
    }

    return ret;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev)
{
    int ret = 0;

    if (!g || drive < 0 || drive >= N_DRIVE || type < 0) {
        return -EINVAL;
    }

    if (type == FLOPPY_TYPE_USER) {
        if (!capable(CAP_SYS_ADMIN))
            return -EPERM;

        if (lock_fdc(0)) {
            return -EINTR;
        }

        if (g->track > 255 || g->head > 1 || g->sector > 255 || g->stretch > 1) {
            unlock_fdc();
            return -EINVAL;
        }

        update_floppy_type(drive, g);
        update_drive_sizes(drive);

    } else {
        if (cmd == SETGEOMETRY) {
            if (g->track > 255 || g->head > 1 || g->sector > 255 || g->stretch > 1) {
                return -EINVAL;
            }
            invalidate_drive(drive);
            update_current(drive, g);
        } else {
            return -EINVAL;
        }
    }

    unlock_fdc();
    return ret;
}
